import { useIntl } from 'react-intl';

import { SubPillarCard } from 'components';

import { useConnectSectionAccess } from '../../../hooks';
import { ConnectAppCard } from './ConnectAppCard';
import {
  StyledConnectCardsGrid,
  StyledConnectSectionRoot,
} from './ConnectSection.styles';
import { GenomePortalCard } from './GenomePortalCard';

export const ConnectSection = () => {
  const { formatMessage } = useIntl();
  const { showGenomePortalCard, isConnectAppFullWidth } =
    useConnectSectionAccess();

  return (
    <StyledConnectSectionRoot data-testid="connect-section">
      <SubPillarCard
        title={formatMessage({
          id: 'ConnectionsCreativity.Home.connect.title',
        })}
        description={formatMessage({
          id: 'ConnectionsCreativity.Home.connect.description',
        })}
      >
        <StyledConnectCardsGrid
          data-testid="connect-cards-grid"
          $fullWidth={isConnectAppFullWidth}
        >
          <ConnectAppCard />
          {showGenomePortalCard && <GenomePortalCard />}
        </StyledConnectCardsGrid>
      </SubPillarCard>
    </StyledConnectSectionRoot>
  );
};
